      case 'LOAD':
      case 'STORE': text += ` ${program.locals[ins.operands[0]]}`; break;
      case 'JMP':
      case 'JZ': text += ` ${pad(jumpTarget(ins))}`; break;
      case 'CALL': text += ` ${program.names[ins.operands[0]]}/${ins.operands[1]}`; break;
      default: break;
    }
    return `${pad(ins.addr)}  ${text}`;
  }).join('\n');
}
